class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        s1, s2 = sum(nums1), sum(nums2)
        if s1 < s2:
            nums1, nums2, s1, s2 = nums2, nums1, s2, s1
        diff = s1 - s2
        gains = sorted([v - 1 for v in nums1] + [6 - v for v in nums2], reverse=True)
        ops = 0
        for g in gains:
            if diff <= 0:
                break
            diff -= g
            ops += 1
        return ops if diff <= 0 else -1

