class Solution {
public:
    int minOperations(vector<int>& nums1, vector<int>& nums2) {
        long long s1 = accumulate(nums1.begin(), nums1.end(), 0LL);
        long long s2 = accumulate(nums2.begin(), nums2.end(), 0LL);
        if (s1 < s2) {
            swap(nums1, nums2);
            swap(s1, s2);
        }
        long long diff = s1 - s2;
        vector<int> gains;
        gains.reserve(nums1.size() + nums2.size());
        for (int v : nums1) gains.push_back(v - 1);
        for (int v : nums2) gains.push_back(6 - v);
        sort(gains.rbegin(), gains.rend());
        int ops = 0;
        for (int g : gains) {
            if (diff <= 0) break;
            diff -= g;
            ops++;
        }
        return diff <= 0 ? ops : -1;
    }
};

