class Solution {
    public int minOperations(int[] nums1, int[] nums2) {
        long s1 = 0, s2 = 0;
        for (int v : nums1) s1 += v;
        for (int v : nums2) s2 += v;
        if (s1 < s2) {
            int[] t = nums1; nums1 = nums2; nums2 = t;
            long ts = s1; s1 = s2; s2 = ts;
        }
        long diff = s1 - s2;
        int m = nums1.length + nums2.length;
        int[] gains = new int[m];
        int k = 0;
        for (int v : nums1) gains[k++] = v - 1;
        for (int v : nums2) gains[k++] = 6 - v;
        Arrays.sort(gains);
        int ops = 0;
        for (int i = m - 1; i >= 0 && diff > 0; i--) {
            diff -= gains[i];
            ops++;
        }
        return diff <= 0 ? ops : -1;
    }
};

